S = "Hakeem Force Academy"
QS = [
 (S, "What is the order of the product of a 3 x 2 matrix and a 2 x 3 matrix?", ["2 x 2", "3 x 3", "3 x 2", "2 x 3"], 1,
  "For a product AB, the inner orders (2 and 2) must match, and the result has the outer orders. So a 3 x 2 matrix times a 2 x 3 matrix gives a 3 x 3 matrix.", "The product in the reverse order (2 x 3 times 3 x 2) would be a 2 x 2 matrix.", [3106]),
 (S, "According to the Hadith in Sahih Muslim, which prophet was a carpenter by profession?", ["Hazrat Zakariya (AS)", "Hazrat Dawud (AS)", "Hazrat Idris (AS)", "Hazrat Ibrahim (AS)"], 0,
  "Sahih Muslim reports that Hazrat Zakariya (AS) was a carpenter.", "Hazrat Dawud (AS) made iron armour, and Hazrat Idris (AS) is commonly said to have been a tailor.", [320]),
 (S, "Which property of multiplication is shown by 9 x 7 = 7 x 9?", ["Associative property", "Distributive property", "Commutative property", "Identity property"], 2,
  "Changing the order of the numbers does not change the product, which is the commutative property.", "Addition is also commutative, but subtraction and division are not.", [3954]),
 (S, "In which province of Pakistan is Rekodiq located?", ["Sindh", "Balochistan", "Punjab", "Khyber Pakhtunkhwa"], 1,
  "Rekodiq is a copper and gold mining site in Chagai district of Balochistan.", "Saindak, another well known mining project, is also in Chagai district.", [2092]),
 (S, "Which organ of the human body pumps blood throughout the body?", ["Lungs", "Kidney", "Liver", "Heart"], 3,
  "The heart is a muscular organ that contracts regularly and pushes blood through the blood vessels.", "A normal adult heart beats about 72 times per minute at rest.", [1166]),
 (S, "Which type of tissue in the human body pumps blood regularly?", ["Cardiac muscle", "Smooth muscle", "Skeletal muscle", "Nervous tissue"], 0,
  "The walls of the heart are made of cardiac muscle, which contracts rhythmically without tiring.", "Cardiac muscle is involuntary, meaning we cannot control it by will.", [3760]),
 (S, "Which companion headed the committee that prepared copies of the Quran during the caliphate of Hazrat Usman (RA)?", ["Hazrat Zaid bin Thabit (RA)", "Hazrat Ali (RA)", "Hazrat Abdullah bin Masud (RA)", "Hazrat Abu Hurairah (RA)"], 0,
  "Hazrat Usman (RA) appointed Hazrat Zaid bin Thabit (RA) to lead the committee that wrote standard copies of the Quran and sent them to major cities.", "Because of this work Hazrat Usman (RA) is called Jami ul Quran.", [3684]),
 (S, "To which caste (community) did Raja Dahir, the ruler of Sindh at the time of Muhammad bin Qasim's invasion, belong?", ["Rajput", "Brahmin", "Jat", "Kshatriya"], 1,
  "Raja Dahir belonged to the Brahmin dynasty that ruled Sindh after the Rai dynasty.", "Chach, the father of Dahir, had founded the Brahmin dynasty of Sindh.", [3651]),
 (S, "Is mass a scalar quantity or a vector quantity?", ["Vector quantity", "Scalar quantity", "Both scalar and vector", "Neither"], 1,
  "Mass has only magnitude and no direction, so it is a scalar quantity.", "Weight is a vector because it acts downward as a force.", [2236]),
 (S, "What is one quarter of one third of 36?", ["4", "2", "3", "9"], 2,
  "One third of 36 is 36/3 = 12. One quarter of 12 is 12/4 = 3.", "One quarter of one third is the same as 1/12 of the number.", [2649]),
 (S, "Which one is different from the rest: Rawalpindi, Lahore, Sindh, Peshawar, Quetta?", ["Lahore", "Sindh", "Quetta", "Rawalpindi"], 1,
  "Rawalpindi, Lahore, Peshawar and Quetta are cities, while Sindh is a province.", "Quetta is the capital of Balochistan and Peshawar is the capital of Khyber Pakhtunkhwa.", [3771]),
 (S, "In which city did the Quraish tribe mainly reside?", ["Madina", "Taif", "Makkah", "Jeddah"], 2,
  "The Quraish were the leading tribe of Makkah and looked after the Kaaba.", "The Holy Prophet (PBUH) himself belonged to the Banu Hashim clan of the Quraish.", [3604]),
 (S, "Who was the leader (commander) of the Quraish army in the Battle of Uhud?", ["Abu Jahl", "Abu Sufyan", "Utba bin Rabia", "Ikrimah bin Abu Jahl"], 1,
  "Abu Sufyan led the Makkan army at Uhud, because Abu Jahl had been killed earlier at Badr.", "Abu Sufyan accepted Islam at the conquest of Makkah in 8 Hijri.", [4415]),
 (S, "With which surah does the Quran begin in its written order?", ["Surah Al-Baqarah", "Surah Al-Ikhlas", "Surah Al-Fatiha", "Surah An-Nas"], 2,
  "The first surah in the Mushaf (written order) is Surah Al-Fatiha, followed by Surah Al-Baqarah.", "Surah Al-Fatiha has 7 verses and is recited in every rakat of prayer.", [639]),
 (S, "Which game is played with a racket and a shuttlecock?", ["Squash", "Tennis", "Table tennis", "Badminton"], 3,
  "Badminton players hit a shuttlecock over a net using rackets.", "Squash is played with a racket and a rubber ball inside a walled court.", [3750, 578]),
]
